// Asigna sucursal a los leads de servicios (Mendoza / Córdoba).
// 1º asesor elegido ("Chatear con Matías" -> MZA, "Chatear con Eugenia" -> CBA),
// 2º característica del teléfono del cliente, 3º taller elegido en el bot.
// sub_origen = el texto exacto de las reglas de Tecnom (ticket 4324):
// 'Mendoza Servicios Renault' (Redoo Mendoza Postventa) o
// 'C. Barros Servicios Renault' (Redoo Córdoba Postventa). Sin sucursal: 'Servicios Renault'.
const CARACT_MENDOZA = ['261', '260', '263', '2622', '2623', '2624', '2625', '2626', '2627'];
const CARACT_CORDOBA = ['351', '352', '353', '354', '356', '357', '358', '3463', '3467', '3468', '3472'];
const SUBORIGEN = { MZA: 'Mendoza Servicios Renault', CBA: 'C. Barros Servicios Renault' };

function numeroLocal(tel) {
  // +54 9 263 475-6075 -> 2634756075
  let d = String(tel || '').replace(/\D/g, '');
  if (d.startsWith('54')) d = d.slice(2);
  if (d.startsWith('9')) d = d.slice(1);
  if (d.startsWith('0')) d = d.slice(1);
  return d;
}

return $input.all().map(item => {
  const data = item.json;
  const body = data.body || {};
  const local = numeroLocal(body.tel || body.from);
  const taller = String(body.suborigen || '').toLowerCase();
  const accion = String(body.accion || '').toLowerCase();

  let sucursal = '';
  let criterio = '';

  if (/mat[ií]as/.test(accion)) {
    sucursal = 'MZA'; criterio = 'asesor elegido en el bot';
  } else if (accion.includes('eugenia')) {
    sucursal = 'CBA'; criterio = 'asesor elegido en el bot';
  } else if (local.length === 10 && CARACT_MENDOZA.some(c => local.startsWith(c))) {
    sucursal = 'MZA'; criterio = 'característica del teléfono';
  } else if (local.length === 10 && CARACT_CORDOBA.some(c => local.startsWith(c))) {
    sucursal = 'CBA'; criterio = 'característica del teléfono';
  } else if (taller.includes('mendoza')) {
    sucursal = 'MZA'; criterio = 'taller elegido en el bot';
  } else if (taller.includes('barros')) {
    sucursal = 'CBA'; criterio = 'taller elegido en el bot';
  }

  data.sub_origen = SUBORIGEN[sucursal] || 'Servicios Renault';
  data.sucursal = sucursal === 'MZA' ? 'Mendoza' : sucursal === 'CBA' ? 'Córdoba' : 'Sin determinar';
  data.criterio_sucursal = criterio || 'sin datos';
  return item;
});

